<?php
declare(strict_types=1);require_once __DIR__.'/config/finance_step16.php';$error=null;$accounts=[];$control=[];$pnl=['income'=>0,'expense'=>0,'profit'=>0,'rows'=>[]];$sync=[];$m=['journals'=>0,'manual'=>0,'legacy_income'=>0,'legacy_royalty'=>0,'statement_pending'=>0];
try{$pdo=business_db();finance_step16_ensure($pdo);$sync=finance_step16_sync_all($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];$accounts=finance_step16_accounts($pdo,$orgId);$control=finance_step16_control_balances($pdo,$orgId);$from=date('Y-m-01');$to=date('Y-m-t');$pnl=finance_step16_pnl($pdo,$orgId,$from,$to);$scalar=function(string $q,array $a=[])use($pdo):int{$s=$pdo->prepare($q);$s->execute($a);return(int)$s->fetchColumn();};$m['journals']=$scalar("SELECT COUNT(*) FROM finance_journals WHERE organization_id=?",[$orgId]);$m['manual']=$scalar("SELECT COUNT(*) FROM finance_manual_transactions WHERE organization_id=? AND status='active'",[$orgId]);$m['statement_pending']=$scalar("SELECT COUNT(*) FROM finance_statement_lines WHERE organization_id=? AND status='pending'",[$orgId]);$m['legacy_income']=$scalar("SELECT COUNT(*) FROM income_entries i WHERE i.organization_id=? AND COALESCE(i.amount,0)>0 AND COALESCE(i.source_sheet,'')<>? AND NOT EXISTS(SELECT 1 FROM finance_source_links f WHERE f.organization_id=i.organization_id AND f.source_type='legacy_income' AND f.source_id=i.id AND f.event_key='confirmed_receipt' AND f.status='active')",[$orgId,BUSINESS_REVERSED_SOURCE_SHEET]);$m['legacy_royalty']=$scalar("SELECT COUNT(*) FROM royalty_entries r WHERE r.organization_id=? AND COALESCE(r.amount,0)>0 AND COALESCE(r.source_sheet,'')<>? AND NOT EXISTS(SELECT 1 FROM finance_source_links f WHERE f.organization_id=r.organization_id AND f.source_type='legacy_royalty' AND f.source_id=r.id AND f.event_key='confirmed_receipt' AND f.status='active')",[$orgId,BUSINESS_REVERSED_SOURCE_SHEET]);}catch(Throwable $e){$error=$e->getMessage();}
function fc_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function fc_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Finance Center - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Finance & Accounting</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_entry.php">+ Entry</a><a class="os-btn" href="finance_cashbook.php">Cashbook</a><a class="os-btn" href="finance_profit_loss.php">P&amp;L</a><a class="os-btn primary" href="index.php">Dashboard</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Finance</div><nav class="os-nav"><a class="active" href="finance_center.php"><i class="dot"></i>Finance Center</a><a href="finance_accounts.php"><i class="dot"></i>Cash / Bank Accounts</a><a href="finance_entry.php"><i class="dot"></i>Manual Entry</a><a href="finance_journal.php"><i class="dot"></i>Journal Ledger</a><a href="finance_cashbook.php"><i class="dot"></i>Cashbook</a><a href="finance_receivable_payable.php"><i class="dot"></i>AR / AP</a><a href="finance_reconciliation.php"><i class="dot"></i>Reconciliation</a><a href="finance_legacy_bridge.php"><i class="dot"></i>Legacy Finance Bridge</a><a href="step16_audit.php"><i class="dot"></i>STEP 16 Audit</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 16 • DOUBLE-ENTRY FINANCE</div><h1>Cash, receivables, payables and profit now reconcile to source transactions.</h1><p>Sales, customer payments/refunds, supplier bills/payments/returns and verified COGS are posted through source-linked double-entry journals. Unknown real bank identity stays in clearly labelled clearing accounts until reconciled.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'FINANCE ENGINE LIVE':'Review required' ?></span><span class="os-chip"><?= $m['journals'] ?> journals</span><span class="os-chip"><?= count($accounts) ?> liquid accounts</span><span class="os-chip"><?= $m['statement_pending'] ?> unmatched statement lines</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Finance diagnostic:</strong> <?= fc_h($error) ?></div><?php endif;?><?php if(!$error):?><section class="s10-kpis"><div class="s10-kpi"><small>Accounts Receivable</small><strong><?= fc_m($control['accounts_receivable']??0) ?></strong><span>GL control balance</span></div><div class="s10-kpi"><small>Accounts Payable</small><strong><?= fc_m($control['accounts_payable']??0) ?></strong><span>GL control balance</span></div><div class="s10-kpi"><small>Inventory Asset</small><strong><?= fc_m($control['inventory_asset']??0) ?></strong><span>Financial inventory balance</span></div><div class="s10-kpi"><small>This Month P&amp;L</small><strong><?= fc_m($pnl['profit']) ?></strong><span>Income <?= fc_m($pnl['income']) ?> • Expense <?= fc_m($pnl['expense']) ?></span></div></section><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-7"><div class="os-title-row"><div><h2>Cash / Bank & Clearing Accounts</h2><p>System clearing accounts are not claimed as real bank accounts.</p></div><a class="os-btn" href="finance_accounts.php">Manage →</a></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Account</th><th>Type</th><th>Institution</th><th>Balance</th><th>State</th></tr></thead><tbody><?php foreach($accounts as $a):?><tr><td><b><?= fc_h($a['account_name']) ?></b><small><?= fc_h($a['account_code']) ?></small></td><td><?= fc_h(strtoupper($a['account_type'])) ?></td><td><?= fc_h($a['institution_name']?:'—') ?></td><td><b><?= fc_m($a['current_balance']) ?></b></td><td><span class="pp-badge <?= $a['is_system_clearing']?'warn':'' ?>"><?= $a['is_system_clearing']?'CLEARING':'REAL / USER' ?></span></td></tr><?php endforeach;?></tbody></table></div></article><article class="os-card pp-span-5"><h2>Accounting Action Queue</h2><div class="s10-list"><div class="s10-row"><div><b>Legacy income not confirmed as cash</b><small>Operational Excel income is not guessed as received money.</small></div><strong><?= $m['legacy_income'] ?></strong></div><div class="s10-row"><div><b>Legacy royalty not confirmed as cash</b><small>Explicit confirmation required.</small></div><strong><?= $m['legacy_royalty'] ?></strong></div><div class="s10-row"><div><b>Purchases clearing</b><small>Bill vs receipt timing / unallocated charges.</small></div><strong><?= fc_m($control['purchases_clearing']??0) ?></strong></div><div class="s10-row"><div><b>Customer advances</b><small>Payments received before an active invoice.</small></div><strong><?= fc_m($control['customer_advances']??0) ?></strong></div></div><div class="pp-actions" style="margin-top:14px"><a href="finance_legacy_bridge.php">Review Legacy →</a><a href="finance_reconciliation.php">Reconcile →</a></div></article></section><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Source Sync</h2><p>Idempotent bridge: repeat page loads do not duplicate journals.</p></div><a href="finance_journal.php">Open Journal →</a></div><div class="os-status-row"><?php foreach($sync as $k=>$v):?><span class="os-chip"><?= fc_h(str_replace('_',' ',ucwords($k,'_'))) ?> <?= (int)$v ?></span><?php endforeach;?></div></section><div class="os-footer-note"><strong>Accounting policy:</strong> GST/tax treatment is not inferred. Supplier tax totals remain inside the source bill total until an explicit tax-accounting policy is configured.</div><?php endif;?></main></div></body></html>